namespace sv_4735e4b39a8145b99079af91f7bd7e66.Services;

public class AppointmentService
{
    private static readonly List<string> _doctors = new()
    {
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Williams",
        "Dr. Patel"
    };

    private static readonly List<string> _allTimeSlots = new()
    {
        "9:00 AM",
        "9:30 AM",
        "10:00 AM",
        "10:30 AM",
        "11:00 AM",
        "11:30 AM",
        "1:00 PM",
        "1:30 PM",
        "2:00 PM",
        "2:30 PM",
        "3:00 PM",
        "3:30 PM",
        "4:00 PM"
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(_doctors);
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateTime date)
    {
        // Stub: return all time slots regardless of doctor/date
        return Task.FromResult(new List<string>(_allTimeSlots));
    }

    public Task<ValidationResult> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var result = new ValidationResult();

        // Reject "taken@example.com" for outstanding balance
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            result.FieldErrors["Email"] = "Account has outstanding balance";
        }

        // Reject "None" insurance with "Dr. Smith"
        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal)
            && string.Equals(doctor, "Dr. Smith", StringComparison.Ordinal))
        {
            result.FieldErrors["Doctor"] = "Selected doctor does not accept self-pay patients";
        }

        // Reject "10:00 AM" as taken (simulating race condition)
        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            result.FieldErrors["TimeSlot"] = "This slot is no longer available";
        }

        return Task.FromResult(result);
    }
}

public class ValidationResult
{
    public Dictionary<string, string> FieldErrors { get; } = new();
    public bool IsValid => FieldErrors.Count == 0;
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_4735e4b39a8145b99079af91f7bd7e66.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="appointment">
    <DataAnnotationsValidator />

    @* STEP 1: Patient Information *@
    <fieldset>
        <legend>Step 1: Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (!string.IsNullOrEmpty(_serverErrors.GetValueOrDefault("Email")))
            {
                <div class="validation-message">@_serverErrors["Email"]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>
    </fieldset>

    @if (!_showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">Next</button>
    }

    @* STEP 2: Appointment Details *@
    @if (_showStep2)
    {
        <fieldset class="mt-4">
            <legend>Step 2: Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor" @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in _doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (!string.IsNullOrEmpty(_serverErrors.GetValueOrDefault("Doctor")))
                {
                    <div class="validation-message">@_serverErrors["Doctor"]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate" @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in _timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (!string.IsNullOrEmpty(_serverErrors.GetValueOrDefault("TimeSlot")))
                {
                    <div class="validation-message">@_serverErrors["TimeSlot"]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="Model.ReasonForVisit" rows="3" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <button type="button" class="btn btn-secondary me-2" @onclick="BackToStep1">Back</button>
            <button type="button" class="btn btn-info me-2" @onclick="CheckAvailability">Check Availability</button>
            <button type="submit" class="btn btn-success">Book Appointment</button>
        </fieldset>
    }
</EditForm>

@if (_bookingConfirmed)
{
    <div class="alert alert-success mt-3">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentModel Model { get; set; } = new();

    private bool _showStep2;
    private bool _bookingConfirmed;
    private List<string> _doctors = new();
    private List<string> _timeSlots = new();
    private Dictionary<string, string> _serverErrors = new();

    private EditContext? _editContext;

    protected override async Task OnInitializedAsync()
    {
        _editContext = new EditContext(Model);
        _doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        _editContext = new EditContext(Model);
        var validationMessageStore = new ValidationMessageStore(_editContext);

        // Validate step 1 fields manually
        var isValid = true;

        if (string.IsNullOrWhiteSpace(Model.PatientName))
            isValid = false;
        if (string.IsNullOrWhiteSpace(Model.Email) || !IsValidEmail(Model.Email))
            isValid = false;
        if (string.IsNullOrWhiteSpace(Model.Phone))
            isValid = false;
        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
            isValid = false;

        // Use DataAnnotations validation for step 1
        if (_editContext.Validate())
        {
            // Additional check: only step 1 fields need to be valid to proceed
            // Since step 2 fields are not yet filled, we check step 1 explicitly
            if (isValid)
            {
                _showStep2 = true;
                _serverErrors.Clear();
            }
        }
        else
        {
            // If step 2 fields cause validation failure but step 1 is fine, still proceed
            if (isValid)
            {
                _showStep2 = true;
                _serverErrors.Clear();
            }
        }
    }

    private void BackToStep1()
    {
        _showStep2 = false;
        _serverErrors.Clear();
    }

    private async Task OnDoctorOrDateChanged()
    {
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            _timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        _serverErrors.Clear();
        _bookingConfirmed = false;

        if (string.IsNullOrEmpty(Model.Doctor) || !Model.AppointmentDate.HasValue || string.IsNullOrEmpty(Model.TimeSlot))
        {
            // Let the built-in validation handle missing fields
            return;
        }

        var result = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.Doctor,
            Model.TimeSlot);

        if (!result.IsValid)
        {
            foreach (var error in result.FieldErrors)
            {
                _serverErrors[error.Key] = error.Value;
            }
        }
        else
        {
            _serverErrors.Clear();
        }
    }

    private async Task HandleSubmit()
    {
        await CheckAvailability();

        if (_serverErrors.Count == 0)
        {
            _bookingConfirmed = true;
        }
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_4735e4b39a8145b99079af91f7bd7e66.Models;

public class AppointmentModel
{
    // Step 1
    [Required(ErrorMessage = "Patient name is required")]
    public string PatientName { get; set; } = "";

    [Required(ErrorMessage = "Email is required")]
    [EmailAddress(ErrorMessage = "Invalid email format")]
    public string Email { get; set; } = "";

    [Required(ErrorMessage = "Phone is required")]
    public string Phone { get; set; } = "";

    [Required(ErrorMessage = "Insurance provider is required")]
    public string InsuranceProvider { get; set; } = "";

    // Step 2
    [Required(ErrorMessage = "Please select a doctor")]
    public string Doctor { get; set; } = "";

    [Required(ErrorMessage = "Date is required")]
    [FutureDate(ErrorMessage = "Date must be in the future")]
    public DateTime? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Please select a time slot")]
    public string TimeSlot { get; set; } = "";

    [Required(ErrorMessage = "Reason for visit is required")]
    [MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters")]
    public string ReasonForVisit { get; set; } = "";
}

public class FutureDateAttribute : ValidationAttribute
{
    protected override ValidationResult? IsValid(object? value, ValidationContext validationContext)
    {
        if (value is DateTime date)
        {
            if (date.Date <= DateTime.Today)
            {
                return new ValidationResult(ErrorMessage);
            }
        }
        return ValidationResult.Success;
    }
}

